// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 initialMint, uint256 burnAmount, uint8 seedOwner) public {
        vm.assume(initialMint <= type(uint256).max / 2);
        vm.assume(burnAmount <= initialMint);
        address owner = address(uint160(uint256(keccak256(abi.encode(seedOwner)))));
        vm.assume(owner != address(0));
        vm.deal(owner, 0);
        vm.prank(owner);
        c = new ERCDDAToken(0, "", "");
        vm.prank(owner);
        c.mintToken(owner, initialMint);
        vm.assume(burnAmount <= c.balanceOf(owner));
        vm.prank(owner);
        c.burn(burnAmount);
        uint256 sumBalances;
        sumBalances += c.balanceOf(owner);
        assertTrue(c.totalSupply() == sumBalances);
    }
}
